style.css:
@-moz-document domain("canva.com") {
/* 1. Hide every single element that could be the logo */
    a[aria-label="Canva"] *, /* Hides everything inside the link */
    a[aria-label="Canva"] svg,
    a[aria-label="Canva"] img,
    [data-test-id="main-nav-logo"] * { 
        display: none !important;
        visibility: hidden !important;
    }
    
    /* 2. Target the main link container by its stable aria-label and apply the custom image */
    a[aria-label="Canva"] {
        /* Set custom dimensions */
        width: 140px !important; 
        height: 40px !important;
        
        /* Your custom image link (the memoji) */
        background-image: url("https://i.imgur.com/xAGXiJK.png") !important; 
        
        /* Ensure the container is visible and acts as a block */
        display: block !important;
        visibility: visible !important;
        
        /* Image display settings */
        background-repeat: no-repeat !important;
        background-position: left center !important; 
        background-size: contain !important; 
    }
}

/* --- CUSTOM VIDEO ICON (MEMOJI) --- */

/* 1. Target the video icon by its surrounding element (often a stable data-test-id) */
/* This targets the icon in the left sidebar menu (often labeled 'Uploads' or 'Elements') */
[data-test-id="video-tab-icon"] img, 
[data-test-id="nav-item-video-tab"] img,
[data-test-id="video-tab-icon"] svg, 
[data-test-id="nav-item-video-tab"] svg {
    display: none !important;
    visibility: hidden !important;
}

/* 2. Target the button container and apply the custom memoji image */
[data-test-id="video-tab-icon"], 
[data-test-id="nav-item-video-tab"] {
    /* Your custom image link (the memoji) */
    background-image: url("https://i.imgur.com/xAGXiJK.png") !important; 
    
    /* Set size for the icon space */
    width: 24px !important; 
    height: 24px !important;
    
    /* Ensure the icon is visible */
    display: block !important;
    visibility: visible !important;
    
    /* Image display settings */
    background-repeat: no-repeat !important;
    background-position: center center !important; 
    background-size: contain !important; 
}
